try:
    s = vars.get('state', {})
    b = config.get('body', {})
    b['outcome'] = 'promise' if s.get('recorded') and s.get('outcome') != 'transferred' else vars.get('outcome', 'not_verified')
    b['reason'] = vars.get('reason', 'failed')
    failed=vars.get('route') in ('safe_failure','failure_fallback') or any(int(vars.get(name,0) or 0)>0 for name in ('dispatch_failure_count','verify_identity_failure_count','get_account_failure_count','transfer_to_agent_failure_count','schedule_callback_failure_count'))
    if failed and not s.get('recorded') and b['outcome'] not in ('transferred','paid'):
        b['outcome']='no_promise' if s.get('verified') else 'not_reached' if s.get('phase') in ('recipient','callback') else 'not_verified'
        b['reason']='service_error' if s.get('verified') else 'no_callback' if s.get('phase')=='callback' else 'unclear' if s.get('phase')=='recipient' else 'failed'
    if b.get('outcome') in ('promise','paid'):
        config['body'].pop('reason', None)
except Exception:
    pass
